# ---------------------------------------------------------------------------
# Durumlu mock dünya — okumalar deterministik, yazmalar sürüm ilerletir
# ---------------------------------------------------------------------------
_DOCS: dict = {}          # document_id -> {"blocks":[...], "ver":int, "kind":str}
_DFS: dict = {}           # df_id -> {"rows":int, "cols":[...]}
_SEQ = {"doc": 0, "df": 0, "art": 0}


def _hid(prefix, *parts):
    h = hashlib.sha1(("|".join(map(str, parts))).encode()).hexdigest()[:6]
    return f"{prefix}_{h}"


def _pad(lines, n=6):
    """Gerçekçi boyut için birkaç dolgu satırı — compaction'a yem."""
    base = list(lines)
    for i in range(n):
        base.append(f"  · detay-{i+1}: (mock alan) değer={100+i*7}")
    return "\n".join(base)


# --- seed veri (deterministik) ---------------------------------------------
def _issue(key):
    kinds = ["Bug", "Story", "Task"]
    st = ["Open", "In Progress", "In Review", "Done"]
    kh = int(hashlib.sha1(key.encode()).hexdigest(), 16)
    return {
        "key": key, "type": kinds[kh % 3], "status": st[(kh >> 3) % 4],
        "assignee": ["Ayşe Demir", "Mehmet Kaya", "Zeynep Ak"][(kh >> 5) % 3],
        "story_points": (kh % 8) + 1, "priority": ["High", "Medium", "Low"][(kh >> 7) % 3],
        "summary": f"{key} — modül davranışı düzeltmesi",
    }


def _project(key):
    kh = int(hashlib.sha1(key.encode()).hexdigest(), 16)
    return {"key": key.upper(), "name": f"{key.title()} Platformu",
            "lead": "Ayşe Demir", "open": kh % 40 + 5, "done": kh % 120 + 30}


# ---------------------------------------------------------------------------
# Generic handler'lar (handler tipine göre)
# ---------------------------------------------------------------------------
def _err_missing(param):
    raise ValueError(f"zorunlu argüman eksik: {param}")


def _resval(name, args):
    rp = TOOL_META[name].get("resource_param")
    return str(args.get(rp, "")) if rp else ""


def _h_schema(name, args):
    tk = _META_RAW[name]["toolkit"]
    return _pad([f"{tk} şeması: blok tipleri [heading, paragraph, table, chart, "
                 f"image, list]; her blok {{block_id, type, ...}}.",
                 "Kullanım: önce create/from_markdown, sonra add_*/edit_*, sonunda finalize."], 3)


def _h_search(name, args):
    q = args.get("query") or args.get("ref") or args.get("name") or args.get("cql") \
        or args.get("filter") or args.get("title") or "*"
    tk = _META_RAW[name]["toolkit"].replace("_toolkit", "")
    hits = [f"  {i+1}. {tk.upper()}-{_hid('R', name, q, i)[2:]} · '{q}' ile eşleşme "
            f"(skor {round(0.9-0.1*i, 2)})" for i in range(5)]
    return _pad([f"{name}: '{q}' için 5 sonuç:"] + hits, 4)


def _h_read(name, args):
    tk = _META_RAW[name]["toolkit"]
    res = _resval(name, args)
    if not res:
        rp = TOOL_META[name].get("resource_param")
        _err_missing(rp or "kaynak")
    if name == "jira_get_issue":
        it = _issue(res)
        return _pad([f"Issue {it['key']}:",
                     f"  summary: {it['summary']}", f"  type: {it['type']}",
                     f"  status: {it['status']}", f"  assignee: {it['assignee']}",
                     f"  story_points: {it['story_points']}", f"  priority: {it['priority']}"], 8)
    if name in ("jira_get_project", "neta_get_project"):
        p = _project(res)
        extra = "  planned_cost: 4.2M TL\n  actual_cost: 3.8M TL\n  budget_util: %90" \
            if name == "neta_get_project" else f"  lead: {p['lead']}"
        return _pad([f"Proje {p['key']} — {p['name']}", f"  open_issues: {p['open']}",
                     f"  done_issues: {p['done']}", extra], 8)
    if name == "confluence_get_page":
        return _pad([f"Sayfa {res}: 'Mimari Kararlar'",
                     "  Bu sayfa servis sınırlarını ve veri akışını tanımlar.",
                     "  Bölümler: Bağlam, Karar, Sonuçlar, Alternatifler."], 10)
    # doküman outline — güncel duruma göre değişir (staleness kaynağı)
    if name.endswith("_get_outline"):
        doc = _DOCS.get(res)
        if not doc:
            return f"Outline {res}: (boş belge, v0)"
        blocks = "\n".join(f"  [{b['block_id']}] {b['type']}: {b['preview']}"
                           for b in doc["blocks"])
        # gerçekçi bir outline uzun olur (blok tipleri, konum, stil notları)
        return _pad([f"Outline {res} (v{doc['ver']}, {len(doc['blocks'])} blok):",
                     blocks,
                     "  düzenleme için block_id'leri kullan; add_* konumu after_block_id ile verilir.",
                     "  blok tipleri: heading/paragraph/table/chart/image/list."], 8)
    if name.endswith("_read_cells"):
        doc = _DOCS.get(res, {"ver": 0})
        return _pad([f"Hücreler {res} (v{doc.get('ver',0)}):",
                     "  A1=Ay B1=Gelir C1=Gider", "  A2=Oca B2=120 C2=80",
                     "  A3=Şub B3=140 C3=95"], 6)
    # genel okuma
    return _pad([f"{name}({res}): kayıt bulundu.",
                 f"  kaynak: {res}", "  durum: aktif"], 8)


def _h_agg(name, args):
    if name == "jira_aggregate":
        return f"jira_aggregate: metric={args.get('metric','count')} → 47 (proje={args.get('project_key','*')})"
    if name == "jira_group_by":
        gf = args.get("group_field", "status")
        return _pad([f"jira_group_by({gf}):", "  Open: 12", "  In Progress: 8",
                     "  In Review: 5", "  Done: 22"], 3)
    if name == "jira_sprint_report":
        return _pad(["Sprint raporu:", "  committed: 40 SP", "  completed: 34 SP",
                     "  carry_over: 6 SP", "  velocity(avg 3 sprint): 32 SP"], 4)
    if name == "jira_worklog_by_person":
        return _pad(["Worklog (kişi bazında):", "  Ayşe Demir: 18h",
                     "  Mehmet Kaya: 22h", "  Zeynep Ak: 15h"], 3)
    if name in ("neta_count", "ldap_org_count", "ldap_company_count"):
        return f"{name}: toplam = {42 if 'company' in name else 17}"
    if name == "analysis_run_sql":
        return _pad([f"SQL sonucu ({args.get('sql','SELECT ...')[:40]}):",
                     "  satır 1: {ay: Oca, gelir: 120}", "  satır 2: {ay: Şub, gelir: 140}",
                     "  (2 satır döndü)"], 4)
    if name == "analysis_run_stats":
        return _pad([f"İstatistik testi ({args.get('test','ttest')}):",
                     "  statistic: 2.31", "  p_value: 0.021", "  anlamlı: evet (α=0.05)"], 4)
    return f"{name}: hesaplandı = {len(str(args))}"


def _h_write(name, args):
    tk = _META_RAW[name]["toolkit"]
    # create → yeni belge/df kimliği üret
    if name.endswith(("_create", "_create_deck", "_from_markdown")):
        _SEQ["doc"] += 1
        did = _hid("doc", name, _SEQ["doc"])
        _DOCS[did] = {"blocks": [{"block_id": "b1", "type": "heading",
                                  "preview": "Başlık"}], "ver": 1, "kind": tk}
        return f"OK: belge oluşturuldu · document_id={did} (v1)"
    if name in ("analysis_load_file", "analysis_load_table"):
        did = args.get("df_id") or _hid("df", name, _SEQ["df"])
        _SEQ["df"] += 1
        _DFS[did] = {"rows": args.get("rows") or 100, "cols": ["ay", "gelir", "gider"]}
        return f"OK: veri yüklendi · df_id={did} ({_DFS[did]['rows']} satır)"
    if name in ("analysis_render_chart", "analysis_revise_chart"):
        _SEQ["art"] += 1
        return f"OK: grafik üretildi · artifact_id={_hid('art', name, _SEQ['art'])}"
    # mevcut belgeye değişiklik → sürüm ilerlet (staleness tetikler)
    did = args.get("document_id")
    if did:
        doc = _DOCS.setdefault(did, {"blocks": [], "ver": 0, "kind": tk})
        doc["ver"] += 1
        verb = name.split("_", 1)[1]
        nb = {"block_id": f"b{len(doc['blocks'])+1}", "type": verb.replace("add_", ""),
              "preview": (str(args.get("title") or args.get("find") or verb))[:30]}
        if "remove" in name and doc["blocks"]:
            doc["blocks"].pop()
        elif "add" in name or "append" in name:
            doc["blocks"].append(nb)
        if name.endswith("_finalize"):
            return f"OK: belge tamamlandı · {did} (v{doc['ver']}, {len(doc['blocks'])} blok)"
        return f"OK: {verb} uygulandı · {did} → v{doc['ver']}"
    return f"OK: {name} uygulandı"


def _h_other(name, args):
    return f"OK: {name} çalıştı"


_HANDLERS = {"schema": _h_schema, "search": _h_search, "read": _h_read,
             "outline": _h_read, "read_cells": _h_read, "agg": _h_agg,
             "write": _h_write, "other": _h_other}


# ---------------------------------------------------------------------------
# TOOL_META (trace-compaction sözleşmesi) + DISPATCH + SCHEMAS
# ---------------------------------------------------------------------------
def _mk_resource(param):
    if not param:
        return None
    return lambda a, _p=param: str(a.get(_p, ""))


TOOL_META = {}
for _n, _m in _META_RAW.items():
    TOOL_META[_n] = {"cat": _m["cat"], "resource": _mk_resource(_m["resource_param"]),
                     "resource_param": _m["resource_param"], "ttl": _m["ttl"],
                     "verbatim": _m["verbatim"]}


def _mk_dispatch(name, htype):
    fn = _HANDLERS[htype]
    return lambda **args: fn(name, args)


DISPATCH = {n: _mk_dispatch(n, _META_RAW[n]["handler"]) for n in _META_RAW}

SCHEMAS = list(SCHEMAS_RAW)

# CWL delimiter — ajan episode bildirimi (Beyond Compaction)
SCHEMAS.append({
    "type": "function",
    "function": {
        "name": "delimiter",
        "description": ("Trace'i episode'lara böl (CWL). Çok veri toplayacaksan ÖNCE "
                        "start(type='expl'); üretim/rapor öncesi start(type='act', "
                        "dependencies=[...]). Bitince end(description)."),
        "parameters": {"type": "object", "properties": {
            "action": {"type": "string", "enum": ["start", "end"]},
            "type": {"type": "string", "enum": ["expl", "act"]},
            "name": {"type": "string"},
            "dependencies": {"type": "array", "items": {"type": "string"}},
            "description": {"type": "string"}},
            "required": ["action"]}}})
